from abc import ABC, abstractmethod
from dataclasses import dataclass, field
from openai import OpenAI

@dataclass
class HarnessState:
    messages: list = field(default_factory=list)
    step: int = 0
    done: bool = False
    results: list = field(default_factory=list)

class HarnessBase(ABC):
    def __init__(self):
        self.state = HarnessState()
    @abstractmethod
    def think(self): pass
    @abstractmethod
    def act(self, action): pass
    @abstractmethod
    def observe(self, result): pass
    def run(self, max_steps=10):
        while not self.state.done and self.state.step < max_steps:
            self.state.step += 1
            action = self.think()
            result = self.act(action)
            self.observe(result)
        return self.state

# 实现具体 Harness
class SimpleHarness(HarnessBase):
    def __init__(self, question):
        super().__init__()
        self.client = OpenAI()
        self.state.messages = [{'role':'user','content':question}]

    def think(self):
        resp = self.client.chat.completions.create(model='deepseek-v4-pro', messages=self.state.messages)
        return resp.choices[0].message.content

    def act(self, action):
        return action  # 简化:直接返回

    def observe(self, result):
        self.state.messages.append({'role':'assistant','content':result})
        if 'DONE' in result:
            self.state.done = True
        self.state.results.append(result)

h = SimpleHarness('你好,简短回复后说DONE')
state = h.run(max_steps=3)
print(f'完成, {state.step} 步')

