# t45-s3: Harness 插件系统
from datetime import datetime

class Plugin:
    """插件基类: 钩子默认空实现, 子类只覆盖关心的。"""
    def before_step(self, state: dict): pass
    def after_think(self, decision: dict): pass
    def after_act(self, result: str, state: dict): pass


class LoggerPlugin(Plugin):
    def before_step(self, state):
        print(f"[{datetime.now():%H:%M:%S}] ▶ Step {state['step']} 开始")
    def after_think(self, decision):
        print(f"  think → 决策: {decision['action']}({decision.get('args','')})")
    def after_act(self, result, state):
        print(f"  act → {result}")


class CostPlugin(Plugin):
    PRICE_PER_TOKEN = 0.001  # 教学用单价

    def __init__(self):
        self.calls = 0
        self.total_cost = 0.0

    def after_act(self, result, state):
        # 假设每次循环 = 1次LLM调用(input 50 + output 30 token)
        self.calls += 1
        cost = (50 + 30) * self.PRICE_PER_TOKEN
        self.total_cost += cost
        print(f"  💰 本次成本 ¥{cost:.3f} (累计 ¥{self.total_cost:.3f})")

    def report(self):
        return f"共 {self.calls} 次调用, 总成本 ¥{self.total_cost:.3f}"


class Harness:
    """最简框架: 循环里调用插件钩子。"""
    def __init__(self, plugins=None, max_steps: int = 3):
        self.plugins = plugins or []
        self.max_steps = max_steps

    def run(self, task: str):
        state = {"step": 0, "task": task}
        for i in range(self.max_steps):
            state["step"] = i + 1
            for p in self.plugins:
                p.before_step(state)
            decision = {"action": "search", "args": task}
            for p in self.plugins:
                p.after_think(decision)
            result = f"搜索结果[{i+1}]: 关于'{task}'的资料"
            for p in self.plugins:
                p.after_act(result, state)
        return state


if __name__ == "__main__":
    cost = CostPlugin()
    h = Harness(plugins=[LoggerPlugin(), cost], max_steps=3)
    h.run("注意力机制")
    print()
    print("=== 成本报表 ===")
    print(cost.report())
    print()
    print("插件的价值: 加日志/加成本都没改 Harness 一行代码")
